fix:
Completely eliminate the type-unsafe raw field, and migrate all getters and setters to use the strongly-typed Enum.
```rust
pub struct SystemPermission {
    permission_state: PermissionState,
}

impl SystemPermission {
    pub fn claimed(&mut self) {
        if self.permission_state == PermissionState::Requested {
            self.permission_state = PermissionState::Claimed;
        }
    }
}
